package com.flipwatch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(FlipwatchConfig.GROUP)
public interface FlipwatchConfig extends Config
{
	String GROUP = "flipwatch-companion";
	String THIRD_PARTY_WARNING = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers";

	@ConfigItem(
		keyName = "liveAdvice",
		name = "Live prijsadvies",
		description = "Haalt openbare instant-prijzen op bij de OSRS Wiki. Handelsdata blijft lokaal.",
		warning = THIRD_PARTY_WARNING,
		position = 0
	)
	default boolean liveAdvice()
	{
		return false;
	}

	@Range(min = 0, max = 5_000_000)
	@ConfigItem(
		keyName = "minimumProfit",
		name = "Minimale orderwinst",
		description = "Markeer advies als sterk vanaf deze geschatte nettowinst.",
		position = 1
	)
	default int minimumProfit()
	{
		return 150_000;
	}

	@ConfigItem(
		keyName = "history",
		name = "Lokale geschiedenis",
		description = "Intern opgeslagen afgeronde GE-orders.",
		hidden = true
	)
	default String history()
	{
		return "[]";
	}
}

package com.flipwatch;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.text.NumberFormat;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Date;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.shadowlabel.JShadowedLabel;

final class FlipwatchPanel extends PluginPanel
{
	private static final Color GREEN = new Color(103, 218, 126);
	private static final Color AMBER = new Color(230, 184, 91);
	private static final Color MUTED = new Color(147, 160, 151);
	private static final NumberFormat NUMBER = NumberFormat.getIntegerInstance(new Locale("nl", "NL"));
	private static final SimpleDateFormat TIME = new SimpleDateFormat("HH:mm", new Locale("nl", "NL"));

	private final Runnable refreshAction;
	private final Runnable websiteAction;
	private final JPanel offersContainer = new JPanel();
	private final JPanel historyContainer = new JPanel();
	private final JLabel statusLabel = new JLabel("Lokale monitoring actief");
	private final JTextArea privacyLabel = new JTextArea("Je accountnaam en handelsgeschiedenis verlaten RuneLite niet.");

	FlipwatchPanel(Runnable refreshAction, Runnable websiteAction)
	{
		this.refreshAction = refreshAction;
		this.websiteAction = websiteAction;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new VerticalContentPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(BorderFactory.createEmptyBorder(12, 10, 12, 10));
		content.setAlignmentX(LEFT_ALIGNMENT);

		content.add(buildHeader());
		content.add(Box.createRigidArea(new Dimension(0, 10)));
		content.add(buildActions());
		content.add(Box.createRigidArea(new Dimension(0, 12)));
		content.add(sectionTitle("GRAND EXCHANGE-SLOTS"));
		content.add(Box.createRigidArea(new Dimension(0, 6)));

		offersContainer.setLayout(new BoxLayout(offersContainer, BoxLayout.Y_AXIS));
		offersContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		offersContainer.setAlignmentX(LEFT_ALIGNMENT);
		offersContainer.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		content.add(offersContainer);
		content.add(Box.createRigidArea(new Dimension(0, 14)));
		content.add(sectionTitle("RECENTE AFRONDINGEN"));
		content.add(Box.createRigidArea(new Dimension(0, 6)));

		historyContainer.setLayout(new BoxLayout(historyContainer, BoxLayout.Y_AXIS));
		historyContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		historyContainer.setAlignmentX(LEFT_ALIGNMENT);
		historyContainer.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		content.add(historyContainer);
		content.add(Box.createVerticalGlue());

		JScrollPane scrollPane = new JScrollPane(content);
		scrollPane.setBorder(null);
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		add(scrollPane, BorderLayout.CENTER);
		showEmpty();
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setAlignmentX(LEFT_ALIGNMENT);
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(59, 76, 63)),
			BorderFactory.createEmptyBorder(12, 12, 12, 12)));

		JShadowedLabel title = new JShadowedLabel("GE FLIPWATCH");
		title.setForeground(GREEN);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 17f));
		title.setAlignmentX(LEFT_ALIGNMENT);
		header.add(title);
		header.add(Box.createRigidArea(new Dimension(0, 5)));

		statusLabel.setForeground(GREEN);
		statusLabel.setFont(statusLabel.getFont().deriveFont(Font.BOLD, 11f));
		statusLabel.setAlignmentX(LEFT_ALIGNMENT);
		header.add(statusLabel);
		header.add(Box.createRigidArea(new Dimension(0, 6)));

		privacyLabel.setForeground(MUTED);
		privacyLabel.setFont(privacyLabel.getFont().deriveFont(10f));
		privacyLabel.setOpaque(false);
		privacyLabel.setEditable(false);
		privacyLabel.setFocusable(false);
		privacyLabel.setLineWrap(true);
		privacyLabel.setWrapStyleWord(true);
		privacyLabel.setRows(3);
		privacyLabel.setColumns(18);
		privacyLabel.setBorder(null);
		privacyLabel.setAlignmentX(LEFT_ALIGNMENT);
		header.add(privacyLabel);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, header.getPreferredSize().height));
		return header;
	}

	private JPanel buildActions()
	{
		JPanel actions = new JPanel(new GridLayout(1, 2, 6, 0));
		actions.setBackground(ColorScheme.DARK_GRAY_COLOR);
		actions.setAlignmentX(LEFT_ALIGNMENT);
		actions.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));

		JButton refresh = button("Advies verversen", GREEN);
		refresh.addActionListener(event -> refreshAction.run());
		JButton website = button("Open website", AMBER);
		website.addActionListener(event -> websiteAction.run());
		actions.add(refresh);
		actions.add(website);
		return actions;
	}

	private static JButton button(String text, Color accent)
	{
		JButton button = new JButton(text);
		button.setFocusable(false);
		button.setBackground(new Color(31, 41, 34));
		button.setForeground(accent);
		button.setBorder(BorderFactory.createLineBorder(new Color(70, 87, 74)));
		button.setFont(button.getFont().deriveFont(Font.BOLD, 10f));
		return button;
	}

	private static JLabel sectionTitle(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(MUTED);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 10f));
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	void update(Map<Integer, TrackedOffer> offers, Map<Integer, MarketAdvice> advice,
		List<OfferHistoryEntry> history, boolean liveAdviceEnabled, int minimumProfit, String status)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> update(offers, advice, history, liveAdviceEnabled, minimumProfit, status));
			return;
		}
		statusLabel.setText(status);
		privacyLabel.setText(liveAdviceEnabled
			? "Live Wiki-prijzen aan. Alleen het item-ID gaat naar de openbare prijsbron."
			: "Lokale modus. Zet ‘Live prijsadvies’ aan in de instellingen voor actuele targets.");

		offersContainer.removeAll();
		List<TrackedOffer> sorted = new ArrayList<>(offers.values());
		sorted.sort(Comparator.comparingInt(TrackedOffer::getSlot));
		if (sorted.isEmpty())
		{
			offersContainer.add(emptyCard("Geen actieve GE-orders gevonden."));
		}
		else
		{
			for (TrackedOffer offer : sorted)
			{
				offersContainer.add(offerCard(offer, advice.get(offer.getItemId()), liveAdviceEnabled, minimumProfit));
				offersContainer.add(Box.createRigidArea(new Dimension(0, 7)));
			}
		}

		historyContainer.removeAll();
		if (history.isEmpty())
		{
			historyContainer.add(emptyCard("Nog geen afgeronde order geregistreerd."));
		}
		else
		{
			for (int index = 0; index < Math.min(5, history.size()); index++)
			{
				historyContainer.add(historyCard(history.get(index)));
				historyContainer.add(Box.createRigidArea(new Dimension(0, 5)));
			}
		}
		offersContainer.revalidate();
		offersContainer.repaint();
		historyContainer.revalidate();
		historyContainer.repaint();
	}

	private JPanel offerCard(TrackedOffer offer, MarketAdvice advice, boolean liveAdviceEnabled, int minimumProfit)
	{
		JPanel card = baseCard();
		String side = offer.isBuy() ? "KOOP" : "VERKOOP";
		String state = stateLabel(offer.getState());
		card.add(line("Slot " + (offer.getSlot() + 1) + " · " + side, state, offer.isBuy() ? AMBER : GREEN, true));
		card.add(Box.createRigidArea(new Dimension(0, 5)));
		card.add(label(offer.getItemName(), Color.WHITE, Font.BOLD, 13f));
		card.add(Box.createRigidArea(new Dimension(0, 7)));
		card.add(line("Limietprijs", gp(offer.getPrice()) + " GP", Color.WHITE, false));
		card.add(line("Gevuld", gp(offer.getQuantityFilled()) + " / " + gp(offer.getTotalQuantity()), Color.WHITE, false));
		if (offer.getQuantityFilled() > 0)
		{
			card.add(line("Gemiddeld", gp(offer.averageFillPrice()) + " GP", Color.WHITE, false));
		}

		if (advice != null)
		{
			card.add(Box.createRigidArea(new Dimension(0, 6)));
			card.add(line(offer.isBuy() ? "Verkoopdoel" : "Live verkooprichtprijs", gp(advice.suggestedSell()) + " GP", GREEN, true));
			if (offer.isBuy())
			{
				int quantity = Math.max(offer.getQuantityFilled(), offer.getTotalQuantity());
				long orderProfit = OfferMath.orderProfit(offer.averageFillPrice(), advice.suggestedSell(), quantity);
				card.add(line("Geschatte orderwinst", signedGp(orderProfit) + " GP", orderProfit >= 0 ? GREEN : new Color(235, 111, 105), true));
				card.add(line("Flipwatch oordeel", orderProfit >= minimumProfit ? "STERK" : "ONDER WINSTVLOER", orderProfit >= minimumProfit ? GREEN : AMBER, true));
			}
			else
			{
				long difference = (long) offer.getPrice() - advice.suggestedSell();
				card.add(line("Jouw limiet vs. live", signedGp(difference) + " GP", difference <= 0 ? GREEN : AMBER, false));
			}
		}
		else if (liveAdviceEnabled)
		{
			card.add(Box.createRigidArea(new Dimension(0, 6)));
			card.add(label("Live prijs wordt opgehaald…", MUTED, Font.PLAIN, 10f));
		}
		return card;
	}

	private JPanel historyCard(OfferHistoryEntry entry)
	{
		JPanel card = baseCard();
		card.add(line(entry.getItemName(), TIME.format(new Date(entry.getCompletedAt())), Color.WHITE, true));
		card.add(Box.createRigidArea(new Dimension(0, 3)));
		String action = "SOLD".equals(entry.getState()) ? "Verkocht" : "Gekocht";
		card.add(line(action, gp(entry.getQuantity()) + " × " + gp(entry.getPrice()) + " GP", MUTED, false));
		return card;
	}

	private static JPanel baseCard()
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(54, 68, 58)),
			BorderFactory.createEmptyBorder(9, 9, 9, 9)));
		card.setAlignmentX(LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		return card;
	}

	private static JPanel emptyCard(String text)
	{
		JPanel card = baseCard();
		JLabel label = label(text, MUTED, Font.PLAIN, 10f);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		card.add(label);
		return card;
	}

	private static JPanel line(String left, String right, Color rightColor, boolean bold)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		JLabel leftLabel = label(left, MUTED, bold ? Font.BOLD : Font.PLAIN, bold ? 10f : 9f);
		JLabel rightLabel = label(right, rightColor, bold ? Font.BOLD : Font.PLAIN, bold ? 10f : 9f);
		rightLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(leftLabel, BorderLayout.CENTER);
		row.add(rightLabel, BorderLayout.EAST);
		return row;
	}

	private static JLabel label(String text, Color color, int style, float size)
	{
		JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(label.getFont().deriveFont(style, size));
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private static String stateLabel(GrandExchangeOfferState state)
	{
		switch (state)
		{
			case BUYING: return "OPEN · KOPEN";
			case BOUGHT: return "GEKOCHT";
			case SELLING: return "OPEN · VERKOPEN";
			case SOLD: return "VERKOCHT";
			case CANCELLED_BUY:
			case CANCELLED_SELL: return "GEANNULEERD";
			default: return state.name();
		}
	}

	private static String gp(long value)
	{
		return NUMBER.format(value);
	}

	private static String signedGp(long value)
	{
		return (value > 0 ? "+" : "") + gp(value);
	}

	private void showEmpty()
	{
		update(java.util.Collections.emptyMap(), java.util.Collections.emptyMap(),
			java.util.Collections.emptyList(), false, 100_000, "Lokale monitoring actief");
	}

	private static final class VerticalContentPanel extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.flipwatch;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.LinkBrowser;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "Flipwatch Companion",
	description = "Tracks your own Grand Exchange offers locally and calculates live flip targets.",
	tags = {"grand exchange", "ge", "flipping", "profit", "trade tracker"}
)
public class FlipwatchPlugin extends Plugin
{
	private static final String WEBSITE = "https://ge-flipwatch-asusu.henri1258.chatgpt.site/";
	private static final int MAX_HISTORY = 100;
	private static final long ADVICE_TTL_MS = 60_000L;
	@Inject private ClientToolbar clientToolbar;
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ItemManager itemManager;
	@Inject private FlipwatchConfig config;
	@Inject private ConfigManager configManager;
	@Inject private OkHttpClient httpClient;
	@Inject private Gson gson;

	private final Map<Integer, TrackedOffer> offers = new LinkedHashMap<>();
	private final Map<Integer, MarketAdvice> advice = new HashMap<>();
	private final Map<Integer, Long> requestedAt = new HashMap<>();
	private final List<OfferHistoryEntry> history = new ArrayList<>();
	private final Set<String> historySignatures = new java.util.HashSet<>();
	private FlipwatchPanel panel;
	private NavigationButton navigationButton;
	private MarketAdvisor marketAdvisor;
	private String status = "Lokale monitoring actief";

	@Override
	protected void startUp()
	{
		loadHistory();
		marketAdvisor = new MarketAdvisor(httpClient, gson);
		panel = new FlipwatchPanel(this::refreshAllAdvice, () -> LinkBrowser.browse(WEBSITE));
		navigationButton = NavigationButton.builder()
			.tooltip("Flipwatch Companion")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		refreshPanel();
		clientThread.invoke(this::refreshOffersFromClient);
		log.info("Flipwatch Companion started");
	}

	@Override
	protected void shutDown()
	{
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}
		offers.clear();
		advice.clear();
		requestedAt.clear();
		history.clear();
		historySignatures.clear();
		panel = null;
		navigationButton = null;
		marketAdvisor = null;
		log.info("Flipwatch Companion stopped");
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		GrandExchangeOffer raw = event.getOffer();
		if (raw.getState() == GrandExchangeOfferState.EMPTY || raw.getItemId() <= 0)
		{
			offers.remove(event.getSlot());
			refreshPanel();
			return;
		}

		String itemName = itemManager.getItemComposition(raw.getItemId()).getName();
		TrackedOffer offer = TrackedOffer.from(event.getSlot(), raw, itemName);
		offers.put(event.getSlot(), offer);
		captureCompletion(offer);
		if (config.liveAdvice())
		{
			requestAdvice(offer.getItemId(), false);
		}
		refreshPanel();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			refreshOffersFromClient();
		}
	}

	private void refreshOffersFromClient()
	{
		GrandExchangeOffer[] currentOffers = client.getGrandExchangeOffers();
		if (currentOffers == null)
		{
			return;
		}

		for (int slot = 0; slot < currentOffers.length; slot++)
		{
			GrandExchangeOffer raw = currentOffers[slot];
			if (raw == null || raw.getState() == GrandExchangeOfferState.EMPTY || raw.getItemId() <= 0)
			{
				offers.remove(slot);
				continue;
			}

			String itemName = itemManager.getItemComposition(raw.getItemId()).getName();
			TrackedOffer offer = TrackedOffer.from(slot, raw, itemName);
			offers.put(slot, offer);
			captureCompletion(offer);
			if (config.liveAdvice())
			{
				requestAdvice(offer.getItemId(), false);
			}
		}
		refreshPanel();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!FlipwatchConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("liveAdvice".equals(event.getKey()))
		{
			if (config.liveAdvice())
			{
				status = "Live prijsadvies actief";
				refreshAllAdvice();
			}
			else
			{
				advice.clear();
				requestedAt.clear();
				status = "Lokale monitoring actief";
				refreshPanel();
			}
		}
		else if ("minimumProfit".equals(event.getKey()))
		{
			refreshPanel();
		}
	}

	void refreshAllAdvice()
	{
		if (!config.liveAdvice())
		{
			status = "Zet Live prijsadvies aan in de instellingen";
			refreshPanel();
			return;
		}
		if (offers.isEmpty())
		{
			status = "Geen actieve GE-orders";
			refreshPanel();
			return;
		}
		status = "Live prijzen ophalen…";
		refreshPanel();
		requestedAt.clear();
		offers.values().stream().map(TrackedOffer::getItemId).distinct().forEach(itemId -> requestAdvice(itemId, true));
	}

	private void requestAdvice(int itemId, boolean force)
	{
		if (marketAdvisor == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		Long previous = requestedAt.get(itemId);
		if (!force && previous != null && now - previous < ADVICE_TTL_MS)
		{
			return;
		}
		requestedAt.put(itemId, now);
		MarketAdvisor activeAdvisor = marketAdvisor;
		activeAdvisor.fetch(itemId, result -> clientThread.invoke(() ->
		{
			if (marketAdvisor != activeAdvisor)
			{
				return;
			}
			advice.put(itemId, result);
			status = "Live prijsadvies bijgewerkt";
			refreshPanel();
		}), failure -> clientThread.invoke(() ->
		{
			if (marketAdvisor != activeAdvisor)
			{
				return;
			}
			status = failure;
			refreshPanel();
		}));
	}

	private void captureCompletion(TrackedOffer offer)
	{
		GrandExchangeOfferState state = offer.getState();
		if (state != GrandExchangeOfferState.BOUGHT && state != GrandExchangeOfferState.SOLD)
		{
			return;
		}
		if (!historySignatures.add(offer.signature()))
		{
			return;
		}
		history.add(0, OfferHistoryEntry.from(offer));
		if (history.size() > MAX_HISTORY)
		{
			history.subList(MAX_HISTORY, history.size()).clear();
		}
		saveHistory();
	}

	private void loadHistory()
	{
		try
		{
			OfferHistoryEntry[] saved = gson.fromJson(config.history(), OfferHistoryEntry[].class);
			if (saved != null)
			{
				history.addAll(Arrays.stream(saved).limit(MAX_HISTORY).collect(Collectors.toList()));
				historySignatures.addAll(history.stream().map(OfferHistoryEntry::getSignature).collect(Collectors.toSet()));
			}
		}
		catch (RuntimeException exception)
		{
			log.debug("Could not load Flipwatch history", exception);
		}
	}

	private void saveHistory()
	{
		configManager.setConfiguration(FlipwatchConfig.GROUP, "history", gson.toJson(history));
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}
		FlipwatchPanel currentPanel = panel;
		Map<Integer, TrackedOffer> offerSnapshot = Collections.unmodifiableMap(new LinkedHashMap<>(offers));
		Map<Integer, MarketAdvice> adviceSnapshot = Collections.unmodifiableMap(new HashMap<>(advice));
		List<OfferHistoryEntry> historySnapshot = Collections.unmodifiableList(new ArrayList<>(history));
		boolean liveAdvice = config.liveAdvice();
		int minimumProfit = config.minimumProfit();
		String currentStatus = status;
		SwingUtilities.invokeLater(() -> currentPanel.update(
			offerSnapshot,
			adviceSnapshot,
			historySnapshot,
			liveAdvice,
			minimumProfit,
			currentStatus));
	}

