final class MarketAdvice
{
	private final int itemId;
	private final int instantBuy;
	private final int instantSell;
	private final long fetchedAt;

	MarketAdvice(int itemId, int instantBuy, int instantSell, long fetchedAt)
	{
		this.itemId = itemId;
		this.instantBuy = instantBuy;
		this.instantSell = instantSell;
		this.fetchedAt = fetchedAt;
	}

	int getItemId() { return itemId; }
	int getInstantBuy() { return instantBuy; }
	int getInstantSell() { return instantSell; }
	long getFetchedAt() { return fetchedAt; }

	int suggestedBuy()
	{
		return Math.max(1, instantSell + 1);
	}

	int suggestedSell()
	{
		return Math.max(1, instantBuy - 1);
	}
}

package com.flipwatch;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
final class MarketAdvisor
{
	private static final String USER_AGENT = "Flipwatch Companion/1.0 (RuneLite Plugin Hub)";
	private final OkHttpClient httpClient;
	private final Gson gson;

	MarketAdvisor(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	void fetch(int itemId, Consumer<MarketAdvice> onSuccess, Consumer<String> onFailure)
	{
		HttpUrl url = new HttpUrl.Builder()
			.scheme("https")
			.host("prices.runescape.wiki")
			.addPathSegments("api/v1/osrs/latest")
			.addQueryParameter("id", Integer.toString(itemId))
			.build();
		Request request = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException exception)
			{
				log.debug("Price request failed for item {}", itemId, exception);
				onFailure.accept("Prijsbron niet bereikbaar");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						onFailure.accept("Prijsbron gaf fout " + response.code());
						return;
					}
					JsonObject root = gson.fromJson(body.charStream(), JsonObject.class);
					JsonObject data = root == null ? null : root.getAsJsonObject("data");
					JsonObject quote = data == null ? null : data.getAsJsonObject(Integer.toString(itemId));
					Integer high = positiveInt(quote, "high");
					Integer low = positiveInt(quote, "low");
					if (high == null || low == null)
					{
						onFailure.accept("Geen tweezijdige live prijs");
						return;
					}
					onSuccess.accept(new MarketAdvice(itemId, high, low, System.currentTimeMillis()));
				}
				catch (RuntimeException exception)
				{
					log.debug("Could not parse price response for item {}", itemId, exception);
					onFailure.accept("Prijsantwoord kon niet worden gelezen");
				}
			}
		});
	}

	private static Integer positiveInt(JsonObject object, String key)
	{
		if (object == null)
		{
			return null;
		}
		JsonElement value = object.get(key);
		if (value == null || value.isJsonNull())
		{
			return null;
		}
		int parsed = value.getAsInt();
		return parsed > 0 ? parsed : null;
	}
}

