package com.flipwatch;

final class OfferMath
{
	private OfferMath()
	{
	}

	static int taxPerItem(int sellPrice)
	{
		return Math.min(5_000_000, Math.max(0, (int) Math.floor(sellPrice * 0.02)));
	}

	static int bufferPerItem(int buyPrice)
	{
		return Math.max(1, (int) Math.ceil(buyPrice * 0.002));
	}

	static int netPerItem(int buyPrice, int sellPrice)
	{
		return sellPrice - buyPrice - taxPerItem(sellPrice) - bufferPerItem(buyPrice);
	}

	static long orderProfit(int buyPrice, int sellPrice, int quantity)
	{
		return (long) netPerItem(buyPrice, sellPrice) * Math.max(0, quantity);
	}
}

package com.flipwatch;

import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

final class TrackedOffer
{
	private final int slot;
	private final int itemId;
	private final String itemName;
	private final int price;
	private final int totalQuantity;
	private final int quantityFilled;
	private final int spent;
	private final GrandExchangeOfferState state;
	private final long updatedAt;

	private TrackedOffer(int slot, int itemId, String itemName, int price, int totalQuantity,
		int quantityFilled, int spent, GrandExchangeOfferState state, long updatedAt)
	{
		this.slot = slot;
		this.itemId = itemId;
		this.itemName = itemName;
		this.price = price;
		this.totalQuantity = totalQuantity;
		this.quantityFilled = quantityFilled;
		this.spent = spent;
		this.state = state;
		this.updatedAt = updatedAt;
	}

	static TrackedOffer from(int slot, GrandExchangeOffer offer, String itemName)
	{
		return new TrackedOffer(slot, offer.getItemId(), itemName, offer.getPrice(),
			offer.getTotalQuantity(), offer.getQuantitySold(), offer.getSpent(), offer.getState(),
			System.currentTimeMillis());
	}

	int getSlot() { return slot; }
	int getItemId() { return itemId; }
	String getItemName() { return itemName; }
	int getPrice() { return price; }
	int getTotalQuantity() { return totalQuantity; }
	int getQuantityFilled() { return quantityFilled; }
	int getSpent() { return spent; }
	GrandExchangeOfferState getState() { return state; }
	long getUpdatedAt() { return updatedAt; }

	boolean isBuy()
	{
		return state == GrandExchangeOfferState.BUYING || state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.CANCELLED_BUY;
	}

	int averageFillPrice()
	{
		return quantityFilled > 0 ? Math.max(1, Math.round((float) spent / quantityFilled)) : price;
	}

	String signature()
	{
		return slot + ":" + itemId + ":" + state.name() + ":" + quantityFilled + ":" + spent;
	}
}

