public class FlipwatchPanelLayoutTest
{
	@Test
	public void fillsTheNarrowRuneLiteSidebarWithoutHorizontalClipping() throws Exception
	{
		AtomicReference<Throwable> failure = new AtomicReference<>();
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				FlipwatchPanel panel = new FlipwatchPanel(() -> { }, () -> { });
				panel.setSize(PluginPanel.PANEL_WIDTH, 600);
				panel.doLayout();

				JScrollPane scrollPane = (JScrollPane) panel.getComponent(0);
				scrollPane.doLayout();
				JViewport viewport = scrollPane.getViewport();
				viewport.doLayout();
				Component view = viewport.getView();

				assertEquals(viewport.getExtentSize().width, view.getWidth());
				Container content = (Container) view;
				content.doLayout();
				Component header = content.getComponent(0);
				assertTrue(header.getX() <= 10);
				assertTrue(header.getX() + header.getWidth() <= content.getWidth());

				layoutTree(panel);
				assertTrue(header.getWidth() > 0);
				assertTrue(((Container) header).getComponent(0).getWidth() > 0);
				BufferedImage preview = new BufferedImage(PluginPanel.PANEL_WIDTH, 600, BufferedImage.TYPE_INT_ARGB);
				Graphics2D graphics = preview.createGraphics();
				try
				{
					panel.printAll(graphics);
				}
				finally
				{
					graphics.dispose();
				}
				File output = new File("build/reports/flipwatch-panel-preview.png");
				assertTrue(output.getParentFile().isDirectory() || output.getParentFile().mkdirs());
				ImageIO.write(preview, "png", output);
			}
			catch (Throwable throwable)
			{
				failure.set(throwable);
			}
		});

		if (failure.get() != null)
		{
			throw new AssertionError(failure.get());
		}
	}

	private static void layoutTree(Container container)
	{
		container.doLayout();
		for (Component component : container.getComponents())
		{
			if (component instanceof Container)
			{
				layoutTree((Container) component);
			}
		}
	}
}

